def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

while True:
    s = input()
    if s == '':
        break
    n = int(s)
    if is_prime(n):
        print(n, '是素数')
    else:
        print(n, '不是素数')

